:root {
  --bg: #0b1220;
  --panel: #111a2e;
  --panel-2: #16223c;
  --line: #22304f;
  --ink: #e8eefb;
  --muted: #9aa8c7;
  --faint: #6b7a9c;
  --accent: #ffb224;
  --accent-ink: #1a1200;
  --green: #3ecf8e;
  --red: #ff6b6b;
  --blue: #6ea8fe;
  --radius: 12px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.skip { position: absolute; left: -999px; top: 0; background: var(--accent); color: var(--accent-ink); padding: 8px 14px; border-radius: 0 0 8px 0; }
.skip:focus { left: 0; }
a { color: var(--blue); }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.shell { max-width: 1180px; margin: 0 auto; padding: 20px 20px 48px; }
.top { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; padding: 6px 0 18px; }
.brand { display: flex; align-items: center; gap: 10px; font-size: 20px; font-weight: 800; letter-spacing: .2px; }
.mark { width: 14px; height: 14px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(255, 178, 36, .18); }
.top-meta { display: flex; gap: 8px; flex-wrap: wrap; }
.chip { background: var(--panel); border: 1px solid var(--line); border-radius: 999px; padding: 4px 11px; font-size: 12.5px; color: var(--muted); }
.chip b { color: var(--ink); font-weight: 650; }
.lede { background: linear-gradient(135deg, #16223c, #0f1830 60%, #1a1408); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px 24px; margin-bottom: 16px; }
.lede h1 { margin: 0 0 8px; font-size: 26px; line-height: 1.25; letter-spacing: -.2px; }
