.fact { background: rgba(11, 18, 32, .55); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; }
.fact span { display: block; font-size: 12px; color: var(--muted); margin-bottom: 2px; }
.fact b { display: block; font-size: 19px; font-weight: 750; }
.fact small { display: block; color: var(--faint); font-size: 12px; }
.controls { display: flex; gap: 12px; align-items: flex-end; flex-wrap: wrap; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; margin-bottom: 14px; }
.field { display: flex; flex-direction: column; gap: 5px; }
.field label, .field .sub { font-size: 12px; color: var(--muted); font-weight: 600; }
.field input, .field select { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; min-width: 200px; }
.field select { min-width: 170px; }
