tbody tr { cursor: pointer; }
tbody tr:hover, tbody tr:focus-visible { background: var(--panel-2); }
tbody tr[data-selected="true"] { background: #1c2c4e; }
th button { background: none; border: 0; padding: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; }
