.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.name b { display: block; font-size: 14.5px; }
.sub { color: var(--muted); font-size: 12.5px; }
.pos { color: var(--green); }
.neg { color: var(--red); }
.implied { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }
.bar { width: 74px; height: 6px; border-radius: 3px; background: #22304f; overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; background: var(--accent); border-radius: 3px; }
