.badge.pre { background: rgba(255, 178, 36, .14); color: var(--accent); border: 1px solid rgba(255, 178, 36, .4); }
.badge.live { background: rgba(62, 207, 142, .12); color: var(--green); border: 1px solid rgba(62, 207, 142, .4); }
.badge.wl { background: rgba(110, 168, 254, .12); color: var(--blue); border: 1px solid rgba(110, 168, 254, .4); margin-left: 6px; }
.empty { padding: 34px 20px; text-align: center; }
.empty h2 { margin: 0 0 6px; font-size: 18px; }
.empty p { color: var(--muted); margin: 0 0 14px; }
.button { background: var(--accent); color: var(--accent-ink); border: 0; border-radius: 8px; padding: 9px 16px; font-weight: 700; }
.button.ghost { background: var(--bg); color: var(--ink); border: 1px solid var(--line); }
.model { padding: 18px 20px; }
.model h2, .detail-section h3 { margin: 0 0 8px; font-size: 17px; }
.model p { color: var(--muted); margin: 0 0 12px; max-width: 88ch; }
.formula { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 13px; line-height: 1.6; overflow-x: auto; margin-bottom: 14px; }
.calib { width: 100%; font-size: 13px; }
.calib th, .calib td { padding: 6px 10px; }
.note { font-size: 13px; color: var(--muted); border-left: 3px solid var(--accent); padding: 2px 0 2px 12px; margin: 12px 0 0; }
dialog.detail { background: var(--panel); color: var(--ink); border: 1px solid var(--line); border-radius: 14px; max-width: 680px; width: calc(100vw - 40px); max-height: calc(100vh - 40px); overflow-y: auto; padding: 0; }
dialog.detail::backdrop { background: rgba(4, 8, 18, .7); }
.detail-head { display: flex; justify-content: space-between; gap: 14px; padding: 20px 22px 0; }
.detail-head h2 { margin: 4px 0 4px; font-size: 22px; }
.detail-head .sub { margin: 0; }
.close { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 7px 12px; height: fit-content; }
.detail-section { padding: 16px 22px 20px; border-top: 1px solid var(--line); margin-top: 16px; }
.equation { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 12px; }
.equation div { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 9px 11px; }
.equation span { display: block; font-size: 12px; color: var(--muted); }
.equation b { font-size: 15px; }
.why { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; font-size: 13.5px; color: var(--muted); }
.why b { color: var(--ink); }
.steps { margin: 0; padding-left: 20px; }
.steps li { margin-bottom: 10px; }
.steps li b { display: block; font-weight: 600; }
.steps .cost { color: var(--muted); font-size: 13px; }
.foot { color: var(--faint); font-size: 12.5px; padding: 4px 2px; }
@media (max-width: 760px) {
  .facts { grid-template-columns: repeat(2, 1fr); }
  .lede h1 { font-size: 21px; }
  .equation { grid-template-columns: repeat(2, 1fr); }
  .field input, .field select { min-width: 0; width: 100%; }
}
